from produire import produire,paras,table,steps
parts=[
('Le carcinome épidermoïde oropharyngé est une tumeur maligne de la muqueuse de l’oropharynx. Les {sites concernés} peuvent être peu visibles lors d’un examen buccal simple.',paras('Amygdales, base de langue et voile font partie des territoires concernés. Une douleur référée vers l’oreille peut révéler la maladie sans lésion otoscopique.')),
('Tabac, alcool et certains papillomavirus humains participent aux risques. Les {profils de patients} ne doivent pas devenir des critères d’exclusion.',paras('Une tumeur liée au HPV peut survenir chez une personne sans tabagisme important. L’absence d’exposition reconnue ne justifie pas d’abandonner le bilan d’une otalgie persistante avec signes pharyngés.')),
('L’infiltration locale et les connexions sensitives peuvent provoquer une douleur projetée. Les {modes de révélation} incluent symptômes pharyngés et adénopathie cervicale.',paras('Une petite lésion amygdalienne ou de base de langue peut rester discrète alors qu’un ganglion est déjà perceptible. L’extension affecte ensuite déglutition, voix, nutrition ou respiration selon le siège.')),
('Une otalgie unilatérale persistante avec oreille normale demande un bilan adapté. Les {signes associés inquiétants} accélèrent l’orientation.',paras('Odynophagie, dysphagie, masse cervicale, saignement, amaigrissement ou lésion indurée justifient un avis ORL rapide. Détresse respiratoire, hémorragie importante ou impossibilité de boire relèvent de l’urgence.')),
('L’entretien précise durée et progression de la douleur. Les {questions extra-auriculaires} recherchent une plainte parfois peu spontanée.',paras('Demander douleur à la déglutition, modification de voix, blocage alimentaire, masse, crachats sanglants et perte de poids. Relever tabac, alcool et antécédents sans culpabilisation ; ne pas expliquer une persistance uniquement par une ancienne otite.')),
('Examiner bouche, oropharynx accessible et toutes les aires cervicales. Les {limites de visibilité} justifient l’endoscopie spécialisée.',paras('Rechercher asymétrie amygdalienne, lésion, induration et ganglions. Une base de langue ou une région profonde ne peut pas être déclarée normale si elle n’a pas été explorée ; compléter l’examen ORL plutôt que répéter les gouttes.')),
('Le {diagnostic différentiel} comprend causes bénignes et autres maladies importantes. La persistance et les signes associés guident l’intensité du bilan.',table(['Profil','Alternative'],[['Douleur à la mastication, examen reproductible.','Cause dentaire ou temporo-mandibulaire.'],['Fièvre, douleur aiguë unilatérale et trismus.','Abcès périamygdalien ou autre infection.'],['Ulcère au contact d’une dent.','Traumatisme, dont la guérison doit être vérifiée.'],['Masse cervicale sans foyer évident.','Autre tumeur, lymphome ou infection selon contexte.']])) ,
('La preuve diagnostique est histologique. Les {examens tissulaires} précisent nature et caractéristiques du cancer.',paras('Biopsie de la lésion ou prélèvement ganglionnaire approprié selon la stratégie spécialisée. Le statut HPV, notamment évalué par p16 et compléments adaptés, contribue à la classification oropharyngée ; il ne remplace pas l’histologie.')),
('Le bilan mesure extension et capacités fonctionnelles. Les {examens de préparation thérapeutique} sont coordonnés par l’équipe spécialisée.',paras('Endoscopie, scanner et/ou IRM, puis bilan à distance selon stade. Évaluer nutrition, dents, déglutition, parole, comorbidités et soutien psychosocial pour préparer la décision et les soins de support.')),
('L’{arbre diagnostique} évite les traitements empiriques successifs qui retardent l’évaluation. La suspicion suffit à organiser l’avis spécialisé.',steps('Confirmer que l’oreille n’explique pas la plainte et rechercher les signes de douleur projetée.', 'Adresser rapidement si persistance inexpliquée ou symptômes suspects, sans attendre un seuil rigide devant une masse.', 'Obtenir histologie et bilan d’extension par la filière ORL.', 'Discuter en équipe multidisciplinaire traitement, fonctions et préférences du patient.')),
('Le traitement dépend du stade, du siège précis et du patient. Les {stratégies spécialisées} associent contrôle tumoral et préservation fonctionnelle.',paras('Chirurgie transorale ou radiothérapie avec ou sans traitement systémique sont discutées selon la situation. La prise en charge ganglionnaire fait partie de la stratégie ; un statut HPV favorable ne justifie pas une réduction improvisée de traitement.', 'Antalgie, soutien nutritionnel, soins dentaires et rééducation de déglutition doivent être intégrés tôt. Les doses oncologiques relèvent d’un protocole spécialisé et ne se déduisent pas de la seule présentation par otalgie.')),
('Le {suivi} recherche récidive, seconde tumeur et séquelles. Il inclut audition et douleur lorsque ces fonctions restent altérées.',paras('Accompagner arrêt du tabac et réduction de l’alcool à risque. Maintenir suivi ORL, dentaire et nutritionnel ; une nouvelle otalgie ou gêne pharyngée doit être signalée sans attendre le rendez-vous ordinaire.')),
('Une oreille normale n’exclut pas un cancer responsable d’otalgie. Persistance, odynophagie et masse cervicale justifient un bilan rapide. L’histologie confirme le diagnostic. La stratégie doit intégrer nutrition et fonctions.','')]
quiz=[('Une tumeur oropharyngée peut-elle provoquer une otalgie sans lésion de l’oreille ?','Oui.'),('Quels sites peuvent être peu visibles ?','Base de langue et régions profondes de l’oropharynx notamment.'),('L’absence de tabac exclut-elle ?','Non.'),('Une adénopathie peut-elle être révélatrice ?','Oui.'),('Quels symptômes pharyngés faut-il demander ?','Odynophagie, dysphagie, voix modifiée et saignement notamment.'),('Une masse cervicale justifie-t-elle d’attendre plusieurs cures de gouttes ?','Non.'),('Une otoscopie normale dispense-t-elle d’examiner le cou ?','Non.'),('Quel examen prouve la nature du cancer ?','L’histologie.'),('Le statut HPV est-il pertinent pour l’oropharynx ?','Oui, dans la classification et l’évaluation tumorale.'),('p16 remplace-t-il la biopsie ?','Non.'),('Pourquoi évaluer la nutrition ?','Elle influence la tolérance et les soins nécessaires.'),('Le traitement est-il toujours chirurgical ?','Non : plusieurs stratégies existent selon le stade et le patient.'),('Un statut HPV favorable permet-il une réduction libre du traitement ?','Non.'),('Que faire d’une nouvelle otalgie après traitement ?','La signaler et réévaluer récidive, séquelle ou autre cause.')]
produire(10,parts,quiz,(7,22))
